from pathlib import Path
import json,sqlite3,pandas as pd,numpy as np
from model import evaluate,fit,cvar
from common import *
ROOT=Path(__file__).parent;OUT=ROOT/'outputs'
def main():
 raw=pd.read_csv(ROOT/'data/fred_response.csv.gz',na_values=['.']);raw['date']=pd.to_datetime(raw.observation_date);raw=raw[(raw.date>='2015-01-01')&(raw.date<='2026-10-30')].sort_values('date');assert not raw.date.duplicated().any();conventions=json.loads((ROOT/'data/quote_conventions.json').read_text());currencies=list(conventions);sourcecols=[x['series'] for x in conventions.values()];missing=raw[sourcecols].isna().sum().to_dict();common=raw.dropna(subset=sourcecols).set_index('date');assert (common[sourcecols]>0).all().all();quotes=pd.DataFrame({c:(1/common[v['series']] if v['invert'] else common[v['series']]) for c,v in conventions.items()});quotes.index.name='date';quotes.to_csv(OUT/'usd_per_currency.csv')
 checks=[]
 for x in json.loads((ROOT/'data/h10_release_cells.json').read_text()):
  actual=raw.set_index('date').loc[x['date'],conventions[x['currency']]['series']];assert abs(actual-x['quoted_value'])<1e-8;checks.append(dict(**x,fred_value=actual,difference=actual-x['quoted_value']))
 pd.DataFrame(checks).to_csv(OUT/'h10_reconciliation.csv',index=False)
 latest=quotes.index.max();base2025=quotes[quotes.index.year==2025].iloc[-1];ytd2026=pd.DataFrame({'currency':currencies,'base_date':quotes[quotes.index.year==2025].index[-1].date().isoformat(),'latest_date':latest.date().isoformat(),'usd_per_unit_change_pct':((quotes.iloc[-1]/base2025-1)*100).to_numpy()});ytd2026.to_csv(OUT/'currency_2026_ytd_context.csv',index=False);monthly=quotes.resample('ME').last();monthly=monthly[monthly.index.to_period('M')<latest.to_period('M')];returns=monthly.pct_change(fill_method=None).dropna();returns.to_csv(OUT/'completed_month_returns.csv');train=returns[returns.index<'2023-01-01'];test=returns[returns.index>='2023-01-01'];assert train.index.max()<test.index.min();assert test.index.max()==pd.Timestamp('2026-09-30')
 flows=pd.read_csv(ROOT/'data/reference_cashflows.csv').set_index('currency').loc[currencies].reset_index();net=(flows.payments_usd_at_base_spot-flows.receipts_usd_at_base_spot).to_numpy();gross=(flows.payments_usd_at_base_spot+flows.receipts_usd_at_base_spot).sum();net_abs=float(np.abs(net).sum());flows['net_usd_at_base_spot']=net;flows.to_csv(OUT/'netting_ledger.csv',index=False)
 h=fit(train.to_numpy(),net);weights=pd.DataFrame({'currency':currencies,'net_usd_at_base_spot':net,'frozen_hedge_fraction':h});weights.to_csv(OUT/'frozen_policy.csv',index=False)
 policies={'No hedge':[0]*5,'Uniform 50%':[.5]*5,'Fitted under 50% cap':h};score=[];paths=[]
 for split,frame in [('train',train),('holdout',test)]:
  for policy,hedges in policies.items():
   r=evaluate(frame.to_numpy(),net,hedges);score.append(dict(split=split,policy=policy,months=len(frame),cvar90=r['cvar90'],worst=r['worst'],mean=r['mean'],assumed_cost=r['cost'],hedged_notional=r['hedged_notional']))
   for dt,loss in zip(frame.index,r['losses']):paths.append(dict(split=split,policy=policy,month=dt.date().isoformat(),hypothetical_extra_cash_cost=loss))
 scores=pd.DataFrame(score);scores.to_csv(OUT/'policy_scorecard.csv',index=False);pd.DataFrame(paths).to_csv(OUT/'policy_monthly_costs.csv',index=False)
 sensitivities=[]
 for cost in [0,5,15,30,50]:
  for cap in [0,.25,.5,.75,1]:
   z=fit(train.to_numpy(),net,cap,cost);r=evaluate(test.to_numpy(),net,z,cost);sensitivities.append(dict(assumed_cost_bps=cost,coverage_cap=cap,holdout_cvar90=r['cvar90'],holdout_worst=r['worst'],hedged_notional=r['hedged_notional']))
 pd.DataFrame(sensitivities).to_csv(OUT/'policy_sensitivity.csv',index=False)
 con=sqlite3.connect(':memory:');flows.to_sql('flows',con,index=False);sql=pd.read_sql_query((ROOT/'reconcile.sql').read_text(),con);sql.to_csv(OUT/'sql_netting.csv',index=False);assert sql.gross_notional.iloc[0]==gross and sql.net_notional.iloc[0]==net_abs
 hold=scores[scores.split=='holdout'];fitted=hold[hold.policy=='Fitted under 50% cap'].iloc[0];uniform=hold[hold.policy=='Uniform 50%'].iloc[0];wins=bool(fitted.cvar90<uniform.cvar90-1e-6);direction='lower' if wins else 'higher or equal';pct=(gross-net_abs)/gross*100
 fig,ax=plt.subplots(figsize=(10,4.8));period=quotes[quotes.index>='2025-01-01'];colors=['#88c8ff','#e8c281','#ada5ef','#7ddbb1','#ef9fb2']
 for c,color in zip(currencies,colors):ax.plot(period.index,period[c]/period[c].iloc[0]*100,label=c,color=color)
 ax.set_ylabel('USD per unit of foreign currency, rebased to 100');ax.set_title('Quote direction matters before measuring dollar exposure',loc='left',pad=43);ax.legend(loc='upper center',bbox_to_anchor=(.5,1.17),ncol=5,frameon=False);savefig(OUT,'currency-paths',fig)
 fig,ax=plt.subplots(figsize=(10,4.8));x=np.arange(3);ax.bar(x,hold.cvar90/1000,color=['#c2d4e3','#f0c787','#83c7ff']);ax.set_xticks(x,['No hedge','Uniform 50%','Fitted, cap 50%']);ax.set_ylabel('Historical adverse-cost tail measure ($000)');ax.set_title('A fitted hedge must beat the simple policy on later months',loc='left',pad=20);savefig(OUT,'hedge-holdout',fig)
 finding=f"Matching same-currency payments and receipts reduces the hypothetical basket’s hedged-notional base from ${gross/1e6:.1f} million gross to ${net_abs/1e6:.1f} million net, a {pct:.1f}% reduction. On the later-month replay, the fitted policy has {direction} empirical 90% CVaR than a uniform 50% hedge (${fitted.cvar90:,.0f} versus ${uniform.cvar90:,.0f})."
 limits='Cash flows are hypothetical, same-currency and same-date, valued in USD at the base spot; legal netting and timing feasibility are assumed. The budget-lock proxy freezes covered cash flows at base spot and charges an assumed 15 basis points per monthly horizon. It is not a quoted forward, option or executed hedge and excludes rate differentials, basis, collateral, credit and bid-ask costs. Historical cash-cost replay is not realized P&L or a forecast. Only '+str(len(test))+' holdout months are available, leaving about '+f'{len(test)*.1:.1f}'+' observations of tail mass. No future coverage guarantee or significant outperformance is established. FRED history may be revised; no real-time vintage backtest is claimed.'
 dump(OUT/'summary.json',dict(finding=finding,limitations=limits,latest_daily=latest.date().isoformat(),last_completed_month=test.index.max().date().isoformat(),train_months=len(train),holdout_months=len(test),missing_counts=missing,raw_rows_in_window=len(raw),common_quote_rows=len(quotes),independent_release_checks=len(checks),gross_notional=float(gross),net_notional=net_abs,netting_reduction_pct=pct,fitted_outperforms_uniform=bool(wins),frozen_weights=h,holdout_scorecard=hold.to_dict('records')))
 body='<section class="section"><h2>Start with the flows that actually offset.</h2><p>'+finding+'</p><div class="note">Observed: official H.10 daily currency quotations, distributed by FRED, through '+latest.date().isoformat()+'. Assumed: the entire company cash-flow basket, hedge charge, settlement dates and budget-lock mechanism. October is partial and excluded from completed-month policy evaluation.</div>'+figure(OUT,'currency-paths','All five series are converted to USD per unit of foreign currency before rebasing. An increase raises the dollar cost of a foreign-currency payment; receipts have the opposite exposure.')+'<h2>Where 2026 stands</h2><p>The latest observed USD price of each foreign currency is compared with the final common quote of 2025. This year-to-date context includes the partial October observation; the policy test below does not treat October as a completed month.</p>'+table(ytd2026)+'<h2>The reference cash-flow basket</h2>'+table(flows)+'<p>Netting within a currency reduces transaction notional, not the underlying residual exchange exposure. Equal hedge fractions on matched gross legs produce the same residual market sensitivity as hedging the net leg, but an assumed charge on gross notional is larger. Cross-currency positions are not legally netted into a single currency.</p><h2>Freeze the fitted policy, then test it</h2><p>The linear program minimizes empirical 90% adverse-cost CVaR over completed months through December 2022, subject to a cap of 50% of absolute net notional. No later month enters the fit. The five hedge fractions remain fixed for January 2023-September 2026. The same hypothetical exposures and charges are replayed for no hedge, uniform 50% and the fitted policy.</p>'+figure(OUT,'hedge-holdout','Completed-month holdout replay using hypothetical dollar exposures and an assumed 15-bp charge. Lower adverse-cost CVaR is preferable in this diagnostic, but the small tail sample does not establish future protection.')+table(hold)+'<h2>What the result supports</h2><p>First verify that opposite flows can settle together. Then compare a proposed allocation against a simple policy using a frozen evaluation period and actual deal costs. A better fitted objective alone is insufficient. This project’s promotion gate is <strong>'+('not established despite a lower diagnostic' if wins else 'not met: the fitted policy does not improve the chosen holdout diagnostic')+'</strong>.</p><p><a href="workbench.html">Change the coverage assumptions</a></p><details><summary>Method and limitations</summary><p>One-month returns use the last common quoted day in each completed calendar month. No missing daily quote is forward-filled. For a net foreign-currency payable marked at base spot, historical extra dollar cost is net exposure × (spot ratio − 1). Covered exposure has zero spot sensitivity in the budget-lock proxy; the assumed charge is added separately. The empirical CVaR objective uses a threshold and excess-loss terms, not a normal-distribution assumption.</p><p>'+limits+'</p></details><h2>Evidence</h2><p><a href="policy_scorecard.csv">Train and holdout scorecard</a> · <a href="policy_monthly_costs.csv">Every monthly replay</a> · <a href="frozen_policy.csv">Frozen weights</a> · <a href="completed_month_returns.csv">Observed monthly returns</a> · <a href="h10_reconciliation.csv">Independent release checks</a> · <a href="sql_netting.csv">SQL netting check</a> · <a href="policy_sensitivity.csv">Cost and cap sensitivity</a></p><p><a href="https://www.federalreserve.gov/releases/h10/">Official Federal Reserve H.10</a> · <a href="https://fred.stlouisfed.org/release?rid=17">FRED release and series</a></p></section>'
 page(ROOT,'report.html','Does the clever hedge beat the simple one?',finding,body)
 controls=''.join(f'<label for="h{i}">{c} net hedge (%)<input id="h{i}" type="number" min="0" max="100" step="any" value="{h[i]*100:.8f}" required></label>' for i,c in enumerate(currencies));form='<section class="section"><p class="note">Hypothetical basket and budget-lock proxy. Historical replay ends September 2026. Reference weights were fitted through 2022; changing the controls is a stress test, not a new optimization or trade recommendation.</p><form id="scenario"><div class="formgrid">'+controls+'<label for="cost">Assumed monthly charge (basis points)<input id="cost" type="number" min="0" max="500" step="any" value="15" required></label></div><button type="submit">Replay the policy</button></form><button type="button" id="uniform">Set all currencies to 50%</button><button type="button" id="fitted">Restore fitted reference</button><div id="results" class="results" aria-live="polite"></div><button id="download" type="button">Download scenario JSON</button><details><summary>Interpret the historical diagnostic</summary><p>'+limits+'</p><p>Positive extra cost is adverse to the payer-oriented net basket. The historical tail measure can be negative if favorable outcomes dominate; it is not floored or presented as a loss probability.</p></details></section>'
 page(ROOT,'workbench.html','Which currency coverage earns its place?','Replay a transparent hedge policy against the simple 50% benchmark.',form,(OUT/'calculator.js').read_text(),dict(currencies=currencies,net=net.tolist(),returns=test.to_numpy().tolist(),months=[x.date().isoformat() for x in test.index],frozen_weights=h,gross_notional=float(gross),net_notional=net_abs))
 (ROOT/'docs/executive_memo.md').write_text('# Currency netting and hedge-policy challenge\n\n'+finding+'\n\n## Decision use\nConfirm same-currency settlement offsets before purchasing hedges on gross flows. Compare any fitted allocation with uniform coverage on later observations, including deal charges. The gate for production adoption remains unestablished: limited later-month tail evidence and unquoted instruments prevent an implementation claim.\n\n## Limits\n'+limits+'\n');print(finding)
if __name__=='__main__':main()
